def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    value = (v1 + v2) / 2
    return {
        "value": value,
        "trace": {
            "values": [v1, v2],
            "average": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
